import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, BookOpen, Check, CheckCheck, ChevronDown, ChevronRight, CloudRain, Database, Download, ExternalLink, Globe2, HelpCircle, Layers3, Leaf, LayoutDashboard, Map as MapIcon, Menu, Minus, Plus, Search, ShieldCheck, SlidersHorizontal, Sparkles, Sprout, Thermometer, TrendingUp, Users, Wheat, Wind, X, TriangleAlert, RotateCcw, CalendarDays, LoaderCircle, Focus, Bookmark, FileText } from 'lucide-react';
import { Area, CartesianGrid, ComposedChart, Line, ReferenceLine, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
