type Page = 'overview' | 'forecast' | 'climate' | 'map' | 'warnings' | 'spatio' | 'sources';
type Country = (typeof countries)[number];
type Risk = { score: number | null; level: string; change: number | null; supply: number | null };
type Row = Country & { risk: Risk; last: { year: number; rice: number | null; population: number }; prediction: { rice: number | null; population: number } };
type Point = { year: number; rice: number | null; population: number };
type Weather = { daily: { time: string[]; temperature_2m_max: (number | null)[]; precipitation_sum: (number | null)[] }; timezone: string; latitude: number; longitude: number };

const labels: Record<Page, string> = { overview: 'Overview', forecast: 'Forecasting', climate: 'Climate Monitor', map: 'Interactive Risk Map', warnings: 'Early Warning', spatio: 'Spatio-temporal', sources: 'Integrated Data' };
const nav = [
  { id: 'overview' as Page, icon: LayoutDashboard, label: 'Overview' },
  { id: 'forecast' as Page, icon: TrendingUp, label: 'Forecasting' },
  { id: 'climate' as Page, icon: CloudRain, label: 'Climate Monitor' },
  { id: 'map' as Page, icon: MapIcon, label: 'Risk Map' },
  { id: 'warnings' as Page, icon: Bell, label: 'Early Warning' },
  { id: 'spatio' as Page, icon: Layers3, label: 'Spatio-temporal' },
];
const { riceModel, populationModel } = recommendedModels(research);
const levelText: Record<string, string> = { high: 'Tinggi', medium: 'Waspada', low: 'Rendah', unknown: 'Data terbatas' };
const levelColor: Record<string, string> = { high: '#d98169', medium: '#d6b46b', low: '#88b69b', unknown: '#b8c6c0' };
const n = (value: number | null | undefined, digits = 2) => value == null ? '—' : formatNumber(value, digits);
const pct = (value: number | null) => value == null ? t("Data tidak tersedia") : `${value >= 0 ? '+' : ''}${n(value)}%`;

function Logo({ small = false }: { small?: boolean }) {
  return <div className={`logo ${small ? 'small' : ''}`}><div className="logo-mark"><ShieldCheck size={29} strokeWidth={1.5} /><Sprout className="logo-sprout" size={15} /></div><span>rice<span className="logo-light">guard</span><i /></span></div>;
}
function Badge({ level, children }: { level: string; children?: ReactNode }) { return <span className={`badge ${level}`}><i />{children || t(levelText[level])}</span>; }
function SectionHead({ title, subtitle, action }: { title: string; subtitle?: string; action?: ReactNode }) { return <div className="section-head"><div><h3>{title}</h3>{subtitle && <p>{subtitle}</p>}</div>{action}</div>; }
function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const dialog = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    dialog.current?.focus();
    const listener = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
      if (event.key === 'Tab' && dialog.current) {
        const items = Array.from(dialog.current.querySelectorAll<HTMLElement>('button, a[href], input, select, [tabindex="0"]'));
        const first = items[0], last = items.at(-1);
        if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
      }
    };
    document.addEventListener('keydown', listener);
    const overflow = document.body.style.overflow; document.body.style.overflow = 'hidden';
    return () => { document.removeEventListener('keydown', listener); document.body.style.overflow = overflow; previous?.focus(); };
  }, [onClose]);
  return <div className="modal-backdrop" onClick={onClose}><div ref={dialog} tabIndex={-1} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide ? 'wide' : ''}`} onClick={event => event.stopPropagation()}><div className="modal-head"><h2>{title}</h2><button className="icon-button" aria-label={t("Tutup dialog")} onClick={onClose}><X size={20} /></button></div>{children}</div></div>;
}

function ForecastChart({ history, projected, year, full = false }: { history: Point[]; projected: Point[]; year: number; full?: boolean }) {
  const last = history.at(-1)!;
  const data = [...history.filter(point => point.year >= (full ? 1961 : 2000)).map(point => ({ year: point.year, rice: point.rice, population: point.population, riceForecast: point.year === last.year ? point.rice : undefined, populationForecast: point.year === last.year ? point.population : undefined })), ...projected.map(point => ({ year: point.year, riceForecast: point.rice, populationForecast: point.population }))];
  return <div className="forecast-chart" role="img" aria-label={t("Grafik produksi padi dan populasi historis hingga 2024 dan proyeksi {p0}", {p0: year})}><ResponsiveContainer width="100%" height="100%"><ComposedChart data={data} margin={{ left: -20, right: -17, top: 12, bottom: 0 }}>
    <defs><linearGradient id="rice-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4f9979" stopOpacity={0.24} /><stop offset="100%" stopColor="#4f9979" stopOpacity={0.015} /></linearGradient><linearGradient id="pop-gradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#dfb465" stopOpacity={0.20} /><stop offset="100%" stopColor="#dfb465" stopOpacity={0.01} /></linearGradient></defs>
    <CartesianGrid strokeDasharray="3 5" stroke="#e7ece7" vertical={false} />
    <XAxis dataKey="year" type="number" domain={['dataMin', 'dataMax']} ticks={full ? [1961, 1980, 2000, 2024, year] : [2000, 2005, 2010, 2015, 2020, 2024, year]} axisLine={false} tickLine={false} tick={{ fill: '#8b948d', fontSize: 10 }} dy={7} />
    <YAxis yAxisId="rice" axisLine={false} tickLine={false} tick={{ fill: '#759183', fontSize: 10 }} width={49} tickFormatter={value => n(value, 0)} domain={[0, 'auto']} />
    <YAxis yAxisId="population" orientation="right" axisLine={false} tickLine={false} tick={{ fill: '#b19a6d', fontSize: 10 }} width={48} tickFormatter={value => n(value, 0)} domain={[0, 'auto']} />
    <Tooltip content={({ active, payload, label }) => active && payload?.length ? <div className="chart-tooltip"><strong>{label}{Number(label) > 2024 ? t(' · Proyeksi') : ''}</strong>{payload.filter(item => item.value != null).map(item => <div key={String(item.dataKey)}><i style={{ background: item.color }} /><span>{String(item.dataKey).includes('rice') ? t('Padi') : t('Populasi')}</span><b>{n(Number(item.value))} {t("juta")}</b></div>)}</div> : null} />
    <Area yAxisId="rice" type="monotone" dataKey="rice" stroke="#398065" fill="url(#rice-gradient)" strokeWidth={2.4} isAnimationActive={false} />
    <Area yAxisId="population" type="monotone" dataKey="population" stroke="#d2ad67" fill="url(#pop-gradient)" strokeWidth={2.2} isAnimationActive={false} />
    <Line yAxisId="rice" type="monotone" dataKey="riceForecast" stroke="#398065" strokeDasharray="5 5" strokeWidth={2.4} dot={false} isAnimationActive={false} />
    <Line yAxisId="population" type="monotone" dataKey="populationForecast" stroke="#d2ad67" strokeDasharray="5 5" strokeWidth={2.2} dot={false} isAnimationActive={false} />
    <ReferenceLine yAxisId="rice" x={2024} stroke="#a8b3a8" strokeDasharray="3 4" label={{ value: t("PROYEKSI →"), fill: '#8f998f', fontSize: 8, position: 'insideTopRight' }} />
  </ComposedChart></ResponsiveContainer></div>;
}

function RiskMap({ rows, selected, onSelect, expanded = false }: { rows: Row[]; selected: string; onSelect: (code: string) => void; expanded?: boolean }) {
  const [geo, setGeo] = useState<FeatureCollection | null>(null);
  const [error, setError] = useState(false);
  const [zoom, setZoom] = useState(1);
  const [layer, setLayer] = useState('risk');
  const [hover, setHover] = useState<string | null>(null);
  useEffect(() => { fetch('/sea.geojson').then(response => { if (!response.ok) throw new Error('map'); return response.json(); }).then(setGeo).catch(() => setError(true)); }, []);
  const projection = useMemo(() => geoMercator().center([117, 9]).scale(430).translate([270, 164]), []);
  const path = useMemo(() => geoPath(projection), [projection]);
  const hovered = rows.find(row => row.code === hover);
  const fill = (row?: Row) => !row ? '#e6ebe3' : layer === 'temperature' ? row.temperature >= 1.5 ? '#d98169' : row.temperature >= 1.1 ? '#d6b46b' : '#88b69b' : layer === 'production' ? row.last.rice == null ? '#b8c6c0' : row.last.rice > 20 ? '#53866c' : row.last.rice > 2 ? '#8ab397' : '#bcd2be' : levelColor[row.risk.level];
  return <div className={`risk-map-wrapper ${expanded ? 'expanded' : ''}`}>
    <div className="map-tools"><span><i />{t("11 negara · Asia Tenggara")}</span><select aria-label={t("Layer peta")} value={layer} onChange={event => setLayer(event.target.value)}><option value="risk">{t("Risiko pangan")}</option><option value="temperature">{t("Anomali suhu (demo)")}</option><option value="production">{t("Produksi padi")}</option></select></div>
    <div className="map-canvas">
      {error ? <div className="empty-state">{t("Peta gagal dimuat. Gunakan daftar negara di bawah.")}</div> : !geo ? <div className="empty-state"><LoaderCircle className="spin" />{t("Memuat peta…")}</div> : <svg viewBox="0 0 540 335" aria-label={t("Peta interaktif Asia Tenggara")}>
        <defs><pattern id="map-grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M 35 0 L 0 0 0 35" fill="none" stroke="#d7e0d7" strokeWidth="0.5" opacity="0.45" /></pattern><clipPath id="map-clip"><rect width="540" height="335" /></clipPath></defs>
        <rect width="540" height="335" fill="#f0f4ed" /><rect width="540" height="335" fill="url(#map-grid)" />
        <g clipPath="url(#map-clip)"><g transform={`translate(${270 * (1 - zoom)},${167 * (1 - zoom)}) scale(${zoom})`}>
          {geo.features.map((feature: Feature) => { const code = feature.properties?.code; const row = rows.find(item => item.code === code); return <path key={code} d={path(feature) || ''} fill={fill(row)} stroke={code === selected ? '#194f3c' : '#f6f8f3'} strokeWidth={code === selected ? 2 : 1.3} className={row ? 'map-country' : ''} tabIndex={row ? 0 : undefined} role={row ? 'button' : undefined} aria-label={row ? `${t(row.name)}: ${t(levelText[row.risk.level])}` : undefined} onMouseEnter={() => row && setHover(code)} onMouseLeave={() => setHover(null)} onFocus={() => row && setHover(code)} onBlur={() => setHover(null)} onClick={() => row && onSelect(code)} onKeyDown={event => { if (row && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); onSelect(code); } }}><title>{t(row?.name || feature.properties?.name)}</title></path>; })}
          {rows.map(row => { const xy = projection(row.label as [number, number])!; return <g key={row.code} className="map-label" onClick={() => onSelect(row.code)}><text x={xy[0]} y={xy[1]} textAnchor="middle">{t(row.name)}</text></g>; })}
          {['SGP', 'BRN'].map(code => { const row = rows.find(item => item.code === code)!; const xy = projection([row.lon, row.lat])!; return <circle key={code} cx={xy[0]} cy={xy[1]} r={4} fill={fill(row)} stroke="#fff" strokeWidth={1.5} role="button" tabIndex={0} aria-label={t("{p0}: {p1}", {p0: row.name, p1: levelText[row.risk.level]})} className="map-country" onClick={() => onSelect(code)} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onSelect(code); } }} />; })}
        </g></g>
        <text x="451" y="92" className="ocean-label" transform="rotate(-10 451 92)">{t("PACIFIC OCEAN")}</text><text x="54" y="258" className="ocean-label">{t("INDIAN OCEAN")}</text>
      </svg>}
      {hovered && <div className="map-tooltip"><strong>{hovered.flag} {t(hovered.name)}</strong><span>{layer === 'temperature' ? t("+{p0}°C · Simulasi", {p0: n(hovered.temperature, 1)}) : layer === 'production' ? t("{p0} juta ton padi", {p0: n(hovered.last.rice)}) : t("Skor {p0}/100 · {p1}", {p0: hovered.risk.score ?? '—', p1: levelText[hovered.risk.level]})}</span></div>}
      <div className="zoom-tools"><button aria-label={t("Perbesar peta")} onClick={() => setZoom(value => Math.min(1.7, value + 0.15))}><Plus size={16} /></button><button aria-label={t("Perkecil peta")} onClick={() => setZoom(value => Math.max(0.85, value - 0.15))}><Minus size={16} /></button><button aria-label={t("Reset peta")} onClick={() => setZoom(1)}><Focus size={16} /></button></div>
      <div className="map-north"><span>{t("N")}</span><ArrowUpRight size={17} /></div>
      <div className="map-attribution">{t("© Natural Earth · Batas negara 1:110m")}</div>
    </div>
    <div className="map-legend">{layer === 'risk' ? <><span><i style={{ background: levelColor.low }} />{t("Rendah")}</span><span><i style={{ background: levelColor.medium }} />{t("Waspada")}</span><span><i style={{ background: levelColor.high }} />{t("Tinggi")}</span><span><i style={{ background: levelColor.unknown }} />{t("Data terbatas")}</span></> : layer === 'temperature' ? <><span><i style={{ background: '#88b69b' }} />{t("&lt; 1,1°C")}</span><span><i style={{ background: '#d6b46b' }} />{t("1,1–1,4°C")}</span><span><i style={{ background: '#d98169' }} />{t("≥ 1,5°C")}</span></> : <><span><i style={{ background: '#bcd2be' }} />{t("≤ 2 juta ton")}</span><span><i style={{ background: '#8ab397' }} />{t("2–20 juta")}</span><span><i style={{ background: '#53866c' }} />{t("&gt; 20 juta")}</span></>}<span className="legend-note">{layer === 'production' ? t("Historis 2024") : t("Skenario eksploratif")}</span></div>
  </div>;
}

function App() {
  const language = useLanguage();
  const [page, setPage] = useState<Page>('overview');
  const [country, setCountry] = useState('SEA');
  const [year, setYear] = useState(2030);
  const [scenario, setScenario] = useState('notebook');
  const [stress, setStress] = useState(0);
  const [range, setRange] = useState(false);
  const [menu, setMenu] = useState(false);
  const [search, setSearch] = useState('');
  const [notifications, setNotifications] = useState(false);
  const [modal, setModal] = useState<'method' | 'report' | 'help' | null>(null);
  const [riskFilter, setRiskFilter] = useState('all');
  const [watchlist, setWatchlist] = useState<string[]>(() => { try { const saved = JSON.parse(localStorage.getItem('riceguard-watchlist') || '[]'); return Array.isArray(saved) ? saved.filter(code => countries.some(item => item.code === code)) : []; } catch { return []; } });
  const [toast, setToast] = useState('');
  const [weather, setWeather] = useState<Weather | null>(null);
  const [weatherCountry, setWeatherCountry] = useState('IDN');
  const [weatherState, setWeatherState] = useState<'idle' | 'loading' | 'error' | 'success'>('idle');
  const [analysis, setAnalysis] = useState<{ summary: string; actions: string[] } | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [analysisMode, setAnalysisMode] = useState('');
  const analysisRequest = useRef(0);
  const weatherRequest = useRef(0);
  const notebookActive = country === 'SEA' && scenario === 'notebook';
  const effectiveScenario = notebookActive ? 'regional_forecast' : scenario === 'notebook' ? 'trend' : scenario;
  useEffect(() => { if (notebookActive && year > 2030) setYear(2030); }, [notebookActive, year]);
  const history = useMemo(() => {
    const points = seriesFor(snapshot, country);
    return notebookActive ? points.map((point: Point) => point.year === 2024 ? { ...point, rice: research.forecast.baseline2024.rice / 1e6, population: research.forecast.baseline2024.population / 1e6 } : point) : points;
  }, [country, notebookActive]);
  const projected = useMemo(() => notebookActive ? notebookForecast(research, Math.min(year, 2030), riceModel, populationModel, stress) : forecast(history, year, effectiveScenario, stress), [history, year, effectiveScenario, stress, notebookActive, riceModel, populationModel]);
  const climate = climateFor(country);
  const risk = indicator(history, projected, climate) as Risk;
  const last = history.at(-1)!;
  const end = projected.at(-1)!;
  const prev = history.at(-2)!;
  const countryName = country === 'SEA' ? t("Asia Tenggara") : t(countries.find(item => item.code === country)!.name);
  const rows = useMemo(() => countries.map(item => { const data = seriesFor(snapshot, item.code); const projection = forecast(data, year, scenario === 'notebook' ? 'trend' : scenario, stress); return { ...item, risk: indicator(data, projection, climateFor(item.code)), last: data.at(-1), prediction: projection.at(-1) }; }) as Row[], [year, scenario, stress]);
  const alerts = [...rows].filter(row => row.risk.score != null && row.risk.score >= 30).sort((a, b) => (b.risk.score || 0) - (a.risk.score || 0));
  const visibleAlerts = alerts.filter(row => (country === 'SEA' || country === row.code) && (riskFilter === 'all' || riskFilter === 'watched' && watchlist.includes(row.code) || row.risk.level === riskFilter));
  const recommendation = insights(countryName, risk, climate, year);
  const searchResults = countries.filter(item => `${item.name} ${t(item.name)} ${item.code}`.toLowerCase().includes(search.toLowerCase()));
  const monitored = countries.find(item => item.code === weatherCountry)!;
  useEffect(() => { analysisRequest.current += 1; setAnalysis(null); setAnalysisMode(''); setAnalyzing(false); }, [country, year, scenario, stress, riceModel, populationModel, language]);
  useEffect(() => { try { localStorage.setItem('riceguard-watchlist', JSON.stringify(watchlist)); } catch { /* Storage may be disabled; in-memory watchlist remains available. */ } }, [watchlist]);
  useEffect(() => { if (toast) { const timer = setTimeout(() => setToast(''), 4000); return () => clearTimeout(timer); } }, [toast]);
  useEffect(() => { if (country !== 'SEA') { setWeatherCountry(country); setWeather(null); setWeatherState('idle'); } }, [country]);
  useEffect(() => { weatherRequest.current += 1; setWeather(null); setWeatherState('idle'); }, [weatherCountry]);
  const go = (next: Page) => { if (next === 'forecast') { setScenario('notebook'); setStress(0); } setPage(next); setMenu(false); setNotifications(false); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const selectCountry = (code: string) => { setCountry(code); setSearch(''); setNotifications(false); };
  const toggleWatch = (code: string) => { const watched = watchlist.includes(code); setWatchlist(items => watched ? items.filter(item => item !== code) : [...items, code]); setToast(watched ? t("Negara dihapus dari daftar pantauan.") : t("Negara ditambahkan ke daftar pantauan.")); };
  const exportCsv = () => {
    const records = [['year', 'country', 'rice_million_tonnes', 'population_million_people', 'status', 'scenario', 'stress_percent'], ...history.map((point: Point) => [point.year, country, point.rice ?? '', point.population, point.year === 2024 ? 'historical_rice_UN_population_projection' : 'historical', '', '']), ...projected.map((point: Point) => [point.year, country, point.rice ?? '', point.population, notebookActive ? 'regional_forecast_with_optional_harvest_loss' : 'exploratory_projection', effectiveScenario, stress])];
    const blob = new Blob(['\uFEFF' + records.map(row => row.join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `riceguard-${country}-${year}.csv`; anchor.click(); URL.revokeObjectURL(url); setToast(t("Data historis dan proyeksi berhasil diekspor."));
  };
  const loadWeather = async () => {
    const request = ++weatherRequest.current;
    setWeatherState('loading'); setWeather(null);
    try {
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${monitored.lat}&longitude=${monitored.lon}&daily=temperature_2m_max,precipitation_sum&timezone=auto&forecast_days=7`;
      const response = await fetch(url, { signal: AbortSignal.timeout(20000) });
      if (!response.ok) throw new Error(t("Weather unavailable"));
      const data = await response.json();
      if (!data.daily?.time?.length || !data.daily.temperature_2m_max?.some((value: unknown) => typeof value === 'number') || !data.daily.precipitation_sum?.some((value: unknown) => typeof value === 'number')) throw new Error(t("No weather data"));
      if (request === weatherRequest.current) { setWeather(data); setWeatherState('success'); }
    } catch { if (request === weatherRequest.current) setWeatherState('error'); }
  };
  const analyze = async () => {
    const request = ++analysisRequest.current;
    setAnalyzing(true);
    try {
      const response = await fetch('/api/analyze', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ country: countryName, year, scenario: effectiveScenario, language, stress, risk, climate }), signal: AbortSignal.timeout(30000) });
      if (!response.ok) throw new Error(t("Not configured"));
      const result = await response.json();
      if (!result.summary || !Array.isArray(result.actions)) throw new Error(t("Invalid result"));
      if (request === analysisRequest.current) { setAnalysis(result); setAnalysisMode(t("AI terhubung · Perlu validasi manusia")); }
    } catch { if (request === analysisRequest.current) { setAnalysis(recommendation); setAnalysisMode(t("Analisis lokal · Aturan transparan, belum model AI terlatih")); } }
    finally { if (request === analysisRequest.current) setAnalyzing(false); }
  };

  const chartCard = <section className="card chart-card"><SectionHead title={t("Produksi dan populasi. Satu perspektif.")} subtitle={t("Produksi padi vs populasi · {p0}", {p0: countryName})} action={<div className="segmented"><button className={!range ? 'selected' : ''} onClick={() => setRange(false)}>2000–{year}</button><button className={range ? 'selected' : ''} onClick={() => setRange(true)}>1961–{year}</button></div>} />
    <div className="chart-legend"><span><i className="green" />{t("Produksi padi")}{' '}<small>{t("(juta ton · kiri)")}</small></span><span><i className="gold" />{t("Populasi")}{' '}<small>{t("(juta jiwa · kanan)")}</small></span></div>
    <div className="forecast-method-label">{t("Solid lines show the past. Dashed lines show the forecast.")}{stress > 0 && t(" Harvest-loss scenario: {p0}%.", {p0: stress})}</div><ForecastChart history={history} projected={projected} year={year} full={range} />
    <div className="projection-summary"><div><span><Wheat size={14} /> {t("Padi di")}{' '}{year}</span><strong>{n(end.rice)} <small>{t("juta ton")}</small></strong><em className={(changePercent(end.rice, last.rice) || 0) >= 0 ? 'positive' : 'negative'}>{pct(changePercent(end.rice, last.rice))} <span>{t("dari 2024")}</span></em></div><div><span><Users size={14} /> {t("Populasi di")}{' '}{year}</span><strong>{n(end.population)} <small>{t("juta jiwa")}</small></strong><em className="neutral">{pct(changePercent(end.population, last.population))} <span>{t("dari 2024")}</span></em></div><button className="text-button" onClick={() => setModal('method')}>{t("Metodologi")}{' '}<ArrowUpRight size={14} /></button></div>
  </section>;
  const mapCard = <section className="card map-card"><SectionHead title={t("Satu kawasan, beragam risiko")} subtitle={t("Peta pantauan pangan · Skenario {p0}", {p0: year})} action={<button className="icon-button" title={t("Buka peta penuh")} aria-label={t("Buka peta penuh")} onClick={() => go('map')}><ArrowUpRight size={18} /></button>} /><RiskMap rows={rows} selected={country} onSelect={selectCountry} /></section>;
  const insightCard = <section className="insight-card"><div className="insight-label"><Sparkles size={16} />{t("RICE GUARD INSIGHT")}<span>{t("Skenario")}{' '}{year}</span></div><h3>{risk.change != null && risk.change < 0 ? t("Pertumbuhan penduduk perlu diimbangi produksi.") : t("Data hari ini, keputusan yang lebih siap.")}</h3><p>{risk.change == null ? t("Data padi belum cukup untuk menilai tren produksi per kapita.") : <>{t("Produksi padi per kapita diproyeksikan")}{' '}{risk.change < 0 ? t("menurun") : t("meningkat")} <strong>{n(Math.abs(risk.change), 1)}%</strong>{t(". Pantau tekanan iklim dan perkuat kesiapan pangan.")}</>}</p><button onClick={() => { go('climate'); void analyze(); }}>{t("Lihat rekomendasi")}{' '}<ArrowRight size={16} /></button><Sprout className="insight-plant" size={105} strokeWidth={0.8} /></section>;
  const climateCard = <section className="card climate-card"><SectionHead title={t("Sinyal iklim")} subtitle={t("Input ilustratif untuk simulasi risiko")} action={<span className="mini-badge">{t("DEMO")}</span>} /><div className="climate-numbers"><div><span className="climate-icon warm"><Thermometer size={21} /></span><div><span>{t("Anomali suhu")}</span><strong>+{n(climate.temperature, 1)}<small>{t("°C")}</small></strong><p>{t("Contoh, tanpa baseline observasi")}</p></div></div><div><span className="climate-icon blue"><CloudRain size={21} /></span><div><span>{t("Perubahan curah hujan")}</span><strong>{climate.rain >= 0 ? '+' : ''}{n(climate.rain, 0)}<small>%</small></strong><p>{t("Skenario terhadap kondisi normal")}</p></div></div></div><div className="climate-foot"><span><i />{t("Simulasi · bukan kondisi terkini")}</span><button className="text-button" onClick={() => go('climate')}>{t("Buka monitor")}{' '}<ArrowRight size={14} /></button></div></section>;
  const warningTable = (full = false) => <section className={`card warning-card ${full ? 'full' : ''}`}><SectionHead title={t("Peringatan dini, langkah lebih cepat")} subtitle={t("Indikator eksploratif dari proyeksi dan skenario iklim")} action={!full ? <button className="text-button" onClick={() => go('warnings')}>{t("Lihat semua")}{' '}<ArrowRight size={14} /></button> : <select aria-label={t("Filter tingkat risiko")} value={riskFilter} onChange={event => setRiskFilter(event.target.value)}><option value="all">{t("Semua peringatan")}</option><option value="high">{t("Risiko tinggi")}</option><option value="medium">{t("Waspada")}</option><option value="watched">{t("Daftar pantauan")}</option></select>} />
    <div className="table-scroll"><table><thead><tr><th>{t("NEGARA / WILAYAH")}</th><th>{t("SINYAL UTAMA")}</th><th>{t("SKOR PANTAUAN")}</th><th>{t("TINGKAT RISIKO")}</th><th>{full ? t('PANTAU') : ''}</th></tr></thead><tbody>{(full ? visibleAlerts : visibleAlerts.slice(0, 3)).map(row => <tr key={row.code}><td><button className="country-link" onClick={() => { selectCountry(row.code); go('forecast'); }}><span className="flag">{row.flag}</span><div><strong>{t(row.name)}</strong><small>{t("Proyeksi")}{' '}{year}</small></div></button></td><td><span className="signal-icon">{row.rain < -15 ? <Wind size={15} /> : row.rain > 15 ? <CloudRain size={15} /> : <TrendingUp size={15} />}</span>{row.rain < -15 ? t("Tekanan kekeringan (demo)") : row.rain > 15 ? t("Hujan berlebih (demo)") : t("Tren padi per kapita")}</td><td><div className="score"><span>{row.risk.score}<small>/100</small></span><i><b style={{ width: `${row.risk.score}%`, background: levelColor[row.risk.level] }} /></i></div></td><td><Badge level={row.risk.level} /></td><td><button className="icon-button" aria-label={t("{p0} {p1} {p2} pantauan", {p0: watchlist.includes(row.code) ? 'Hapus' : 'Tambahkan', p1: row.name, p2: watchlist.includes(row.code) ? 'dari' : 'ke'})} onClick={() => toggleWatch(row.code)}><Bookmark size={16} fill={watchlist.includes(row.code) ? '#4c8064' : 'none'} /></button></td></tr>)}</tbody></table>{!visibleAlerts.length && <div className="empty-state"><ShieldCheck size={28} /><strong>{t("Tidak ada peringatan dalam filter ini.")}</strong><span>{t("Ubah negara, skenario, atau filter pantauan.")}</span></div>}</div><div className="table-note"><HelpCircle size={13} />{t("Skor ini tidak memasukkan perdagangan, konsumsi, stok pangan, atau akses pangan.")}{' '}<button onClick={() => setModal('method')}>{t("Pelajari metode")}</button></div>
  </section>;
  const controls = <div className="scenario-controls card"><div><span className="control-label"><SlidersHorizontal size={15} /> {t("PENGATURAN PROYEKSI")}</span><h3>{t("Eksplorasi kemungkinan masa depan.")}</h3><p>{t("Ubah asumsi untuk melihat dampaknya pada indikator pangan.")}</p></div><label>{t("Outlook")}<select value={scenario} onChange={event => setScenario(event.target.value)}><option value="notebook">{t("Recommended forecast")}</option><option value="trend">{t("Recent trend")}</option><option value="infographic">{t("Skenario pertumbuhan infografis")}</option><option value="resilient">{t("Resiliensi · tambahan 1,2% per tahun")}</option></select></label><label>{t("Tekanan hasil panen:")}{' '}<b>{stress}%</b><input type="range" min="0" max="30" step="1" value={stress} onChange={event => setStress(Number(event.target.value))} /><span className="range-label"><small>{t("Tanpa tekanan")}</small><small>{t("−30% di")}{' '}{year}</small></span></label><button className="icon-button" aria-label={t("Reset skenario")} onClick={() => { setScenario('notebook'); setStress(0); setYear(2030); }}><RotateCcw size={17} /></button></div>;

  return <div className="app-shell">
    {menu && <div className="sidebar-backdrop" onClick={() => setMenu(false)} />}
    <aside className={`sidebar ${menu ? 'open' : ''}`}><button className="logo-home" aria-label={t("Beranda Rice Guard")} onClick={() => go('overview')}><Logo /></button><div className="workspace-label"><span className="workspace-dot" />{t("SOUTHEAST ASIA INTELLIGENCE")}</div><div className="nav-label">{t("WORKSPACE")}</div><nav>{nav.map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => go(item.id)}><item.icon size={19} strokeWidth={1.7} /><span>{t(item.label)}</span>{item.id === 'warnings' && <b className="nav-count">{alerts.length}</b>}{item.id === 'spatio' && <span className="soon">{t("NEW")}</span>}</button>)}</nav><div className="nav-divider" /><div className="nav-label">{t("DATA & RESOURCES")}</div><button className={`nav-item ${page === 'sources' ? 'active' : ''}`} onClick={() => go('sources')}><Database size={19} strokeWidth={1.7} /><span>{t("Integrated Data")}</span></button><button className="nav-item" onClick={() => setModal('method')}><BookOpen size={19} strokeWidth={1.7} /><span>{t("Metodologi")}</span></button><div className="sidebar-mission"><div className="mission-art"><Sprout size={57} strokeWidth={1.1} /><span /><span /></div><span className="mission-tag">{t("GROWING A RESILIENT FUTURE")}</span><h4>{t("Menjaga pangan.")}<br />{t("Menjaga masa depan.")}</h4><p>{t("Data terbuka untuk kawasan yang lebih tangguh.")}</p><button onClick={() => setModal('help')}>{t("Tentang Rice Guard")}{' '}<ArrowUpRight size={15} /></button></div><div className="sidebar-bottom"><span className="avatar">{t("RG")}</span><div><strong>{t("Rice Guard Workspace")}</strong><span>{t("Research & exploration")}</span></div><button className="icon-button" aria-label={t("Bantuan")} onClick={() => setModal('help')}><HelpCircle size={18} /></button></div></aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="mobile-menu icon-button" aria-label={t("Buka navigasi")} onClick={() => setMenu(!menu)}><Menu size={21} /></button><Globe2 size={16} /><span>{t("Workspace")}</span><ChevronRight size={13} /><strong>{t(labels[page])}</strong></div><div className="topbar-right"><LanguageSelect /><div className="search-wrap"><Search size={15} /><input aria-label={t("Cari negara")} placeholder={t("Cari negara...")} value={search} onChange={event => setSearch(event.target.value)} onKeyDown={event => { if (event.key === 'Escape') setSearch(''); if (event.key === 'Enter' && searchResults.length) selectCountry(searchResults[0].code); }} /><span className="search-shortcut">↵</span>{search && <div className="search-results">{searchResults.length ? searchResults.map(item => <button key={item.code} onClick={() => selectCountry(item.code)}><span>{item.flag}</span>{t(item.name)}<small>{item.code}</small></button>) : <p>{t("Negara tidak ditemukan.")}</p>}</div>}</div><div className="topbar-divider" /><div className="notification-wrap"><button className={`icon-button notification-button ${notifications ? 'is-open' : ''}`} aria-label={t("{p0} peringatan skenario", {p0: alerts.length})} onClick={() => setNotifications(!notifications)}><Bell size={19} /><i /></button>{notifications && <div className="notification-popover"><div><h4>{t("Peringatan skenario")}{' '}{year}</h4><span>{alerts.length} {t("negara dalam pantauan")}</span></div>{alerts.slice(0, 4).map(row => <button key={row.code} onClick={() => { selectCountry(row.code); go('warnings'); }}><TriangleAlert size={17} /><div><strong>{t(row.name)}</strong><span>{t("Skor")}{' '}{row.risk.score}/100 · {t(levelText[row.risk.level])}</span></div><ChevronRight size={14} /></button>)}{!alerts.length && <p>{t("Tidak ada peringatan pada skenario ini.")}</p>}<p>{t("Contoh analisis · bukan alert operasional")}</p></div>}</div><span className="topbar-avatar">{t("RG")}</span></div></header>
      <main><div className="page-heading"><div><div className="eyebrow"><span />{t("RICE GUARD /")}{' '}{page === 'overview' ? t("REGIONAL OVERVIEW") : t(labels[page]).toUpperCase()}</div><h1>{page === 'overview' ? t("Ketahanan pangan, dalam pantauan.") : page === 'forecast' ? t("A clear view of the years ahead.") : page === 'climate' ? t("Kenali sinyal iklim lebih awal.") : page === 'map' ? t("Lihat risiko dari sudut yang lebih luas.") : page === 'warnings' ? t("Dari sinyal, menuju tindakan.") : page === 'sources' ? t("Satu platform. Data yang terhubung.") : t("Ruang dan waktu, dalam satu perspektif.")}</h1><p>{page === 'overview' ? t("Pantau produksi padi, pertumbuhan penduduk, dan risiko iklim di Asia Tenggara.") : page === 'forecast' ? t("See how much paddy may be produced, how many people it may support, and what needs attention.") : page === 'climate' ? t("Eksplorasi tekanan iklim dan rekomendasi adaptasi untuk wilayah produksi.") : page === 'map' ? t("Klik negara untuk menelusuri produksi, skenario iklim, dan indikator risikonya.") : page === 'warnings' ? t("Identifikasi wilayah yang membutuhkan perhatian berdasarkan skenario proyeksi.") : page === 'sources' ? t("Sumber terbuka, asal-usul yang jelas, dan batasan yang dapat diperiksa.") : t("Eksplorasi GloRice, proyeksi iklim 2030, dan ketidakpastian model BYM2–AR(1).")}</p></div>{page === 'spatio' ? <a className="outline-button report-button" href="/research/spatio-countries-2030.csv" download><Download size={16} />{t("Ekspor area panen")}</a> : <button className="outline-button report-button" onClick={page === 'forecast' ? exportCsv : () => setModal('report')}><Download size={16} />{page === 'forecast' ? t("Download forecast") : t("Ekspor laporan")}</button>}</div>
      {page !== 'spatio' && page !== 'sources' && <div className="filter-bar"><div className="filter-region"><Globe2 size={16} /><select aria-label={t("Wilayah dashboard")} value={country} onChange={event => selectCountry(event.target.value)}><option value="SEA">{t("Seluruh Asia Tenggara")}</option>{countries.map(item => <option key={item.code} value={item.code}>{t(item.name)}</option>)}</select><ChevronDown size={13} /></div><div className="filter-year"><CalendarDays size={15} /><span>{t("Proyeksi")}</span><select aria-label={t("Tahun proyeksi")} value={year} onChange={event => setYear(Number(event.target.value))}>{Array.from({ length: notebookActive ? 6 : 11 }, (_, index) => 2025 + index).map(value => <option key={value} value={value}>{value}</option>)}</select><ChevronDown size={13} /></div><div className="filter-state"><span className="data-dot" /><span>{t("Data historis s.d. 2024")}</span><span className="divider-dot">·</span><button onClick={() => go('sources')}>{t("Sumber terbuka")}{' '}<ExternalLink size={11} /></button></div></div>}
      {page === 'overview' && <>
        <section className="welcome-banner"><div><span className="banner-eyebrow"><Leaf size={13} /> {t("A MORE RESILIENT SOUTHEAST ASIA")}</span><h2>{t("Data yang terhubung.")}<br /><span>{t("Keputusan yang lebih siap.")}</span></h2><p>{t("Menjembatani produksi, populasi, dan iklim")}<br className="desktop-break" /> {t("untuk masa depan pangan yang berkelanjutan.")}</p></div><div className="banner-right"><div className="banner-status"><i />{t("EXPLORATORY DASHBOARD")}</div><div className="banner-orbit"><div className="orbit-ring outer" /><div className="orbit-ring inner" /><div className="orbit-center"><Sprout size={57} strokeWidth={1.2} /></div><span className="orbit-node wheat"><Wheat size={22} /></span><span className="orbit-node people"><Users size={18} /></span><span className="orbit-node cloud"><CloudRain size={21} /></span><svg viewBox="0 0 300 210" className="orbit-lines"><path d="M10 180C60 130 80 190 135 140S215 160 295 95" /><path d="M15 203C80 165 90 220 155 175S255 190 295 150" /></svg></div><span className="banner-region">{t("11 NEGARA")}{' '}<i /> {t("1 VISI KETAHANAN PANGAN")}</span></div></section>
        <div className="kpi-grid"><Metric icon={<Wheat size={20} />} label={t("Produksi padi")} value={n(last.rice)} unit={t("juta ton")} change={changePercent(last.rice, prev.rice)} note={t("2024 · FAO / OWID")} /><Metric icon={<Users size={20} />} label={t("Populasi")} value={n(last.population)} unit={t("juta jiwa")} change={changePercent(last.population, prev.population)} note={t("2024 · Proyeksi UN / OWID")} variant="gold" /><Metric icon={<Activity size={20} />} label={t("Padi per kapita · {p0}", {p0: year})} value={n(risk.supply, 1)} unit={t("kg / jiwa")} change={risk.change} note={t("Indikator produksi · bukan konsumsi")} /><Metric icon={<ShieldCheck size={20} />} label={t("Negara perlu perhatian")} value={String(country === 'SEA' ? alerts.length : alerts.filter(row => row.code === country).length).padStart(2, '0')} unit={t("/ {p0}", {p0: country === 'SEA' ? '11 negara' : '1 negara'})} note={t("Skenario {p0} · risiko eksploratif", {p0: year})} warning /> </div>
        <div className="analytics-grid">{chartCard}{mapCard}</div><div className="secondary-grid">{climateCard}{insightCard}</div>{warningTable()}<div className="source-strip"><div><Database size={16} /><span>{t("Didukung data terbuka")}</span></div><strong>{t("Our World in Data")}</strong><span>{t("FAO")}</span><span>{t("UN Population")}</span><span>{t("Open-Meteo")}{' '}<small>{t("on demand")}</small></span><button onClick={() => go('sources')}>{t("Jelajahi sumber")}{' '}<ArrowRight size={14} /></button></div>
      </>}
      {page === 'forecast' && <><ForecastResearch history={history} projected={projected} year={year} country={countryName} regional={notebookActive} stress={stress} /><details className="card forecast-whatif"><summary><SlidersHorizontal size={16}/>{t("What if the harvest is smaller?")}<ChevronDown size={16}/></summary><div><p>{t("Try a possible harvest loss and see how the outlook changes. This is a scenario, not a prediction of damage.")}</p><label>{t("Harvest loss by {p0}", {p0:year})}: <b>{stress}%</b><input aria-label={t("Harvest loss")} type="range" min="0" max="30" step="1" value={stress} onChange={event=>setStress(Number(event.target.value))}/></label><button className="text-button" onClick={()=>setStress(0)}><RotateCcw size={14}/>{t("Reset harvest loss")}</button></div></details></>}
      {page === 'map' && <><div className="map-page-grid"><section className="card"><SectionHead title={t("Interactive Risk Map")} subtitle={t("Negara sebagai unit analisis · Proyeksi {p0}", {p0: year})} action={<button className="text-button" onClick={() => selectCountry('SEA')}>{t("Reset wilayah")}{' '}<RotateCcw size={14} /></button>} /><RiskMap rows={rows} selected={country} onSelect={selectCountry} expanded /></section><section className="card map-detail"><div className="control-label">{t("WILAYAH TERPILIH")}</div><h2>{t(countryName)}</h2><Badge level={risk.level} /><div className="detail-row"><span>{t("Produksi padi · 2024")}</span><strong>{n(last.rice)} <small>{t("juta ton")}</small></strong></div><div className="detail-row"><span>{t("Populasi · 2024 (UN)")}</span><strong>{n(last.population)} <small>{t("juta jiwa")}</small></strong></div><div className="detail-row"><span>{t("Skor pantauan ·")}{' '}{year}</span><strong>{risk.score ?? '—'} <small>/ 100</small></strong></div><p>{t(recommendation.summary)}</p><button className="primary-button" onClick={() => go('forecast')}>{t("Eksplorasi proyeksi")}{' '}<ArrowRight size={16} /></button><button className="outline-button" onClick={() => setModal('method')}>{t("Cara membaca peta")}</button></section></div><div className="note-card"><MapIcon size={20} /><div><strong>{t("Peta risiko menggunakan data tingkat negara.")}</strong><p>{t("Warna menunjukkan skor eksploratif dari tren produksi per kapita dan input iklim demo. Layer suhu juga merupakan simulasi. Analisis luas panen BYM2–AR(1) tersedia pada menu Spatio-temporal; ukuran tersebut berbeda dari skor risiko pangan di peta ini.")}</p></div></div><div className="country-chips">{rows.map(row => <button className={country === row.code ? 'selected' : ''} key={row.code} onClick={() => selectCountry(row.code)}><span>{row.flag}</span><strong>{t(row.name)}</strong><Badge level={row.risk.level} /></button>)}</div></>}
      {page === 'climate' && <><div className="climate-page-grid">{climateCard}<section className="card"><SectionHead title={t("AI Climate Monitor")} subtitle={t("Analisis berbasis konteks wilayah dan skenario")} action={<Sparkles size={21} className="green-text" />} /><div className="ai-description"><div className="ai-icon"><Sparkles size={25} /></div><div><h3>{t("Dari kondisi, menjadi rekomendasi.")}</h3><p>{t("Analisis menggabungkan proyeksi produksi, populasi, dan tekanan iklim ilustratif. Saat layanan AI belum dikonfigurasi, rekomendasi memakai aturan lokal yang transparan.")}</p></div></div><button className="primary-button" onClick={() => void analyze()} disabled={analyzing}>{analyzing ? <LoaderCircle size={16} className="spin" /> : <Sparkles size={16} />}{analyzing ? t("Menganalisis...") : t("Analisis {p0}", {p0: countryName})}<ArrowRight size={15} /></button></section></div><section className="card weather-card"><SectionHead title={t("Cuaca 7 hari di sentra produksi")} subtitle={t("Prakiraan Open-Meteo · dimuat saat diminta, tanpa API key")} action={<span className="mini-badge">{weather ? t('API TERHUBUNG') : t('ON DEMAND')}</span>} /><div className="weather-controls"><label>{t("Lokasi pemantauan")}<select aria-label={t("Lokasi cuaca")} value={weatherCountry} onChange={event => { setWeatherCountry(event.target.value); setWeather(null); setWeatherState('idle'); }}>{countries.map(item => <option key={item.code} value={item.code}>{t(item.name)} · {t(item.location)}</option>)}</select></label><button className="outline-button" onClick={() => void loadWeather()} disabled={weatherState === 'loading'}>{weatherState === 'loading' ? <LoaderCircle className="spin" size={16} /> : <CloudRain size={16} />}{weatherState === 'loading' ? t("Menghubungkan...") : weather ? t("Perbarui cuaca") : t("Muat cuaca terkini")}</button></div>{weatherState === 'error' && <div className="inline-error"><TriangleAlert size={17} />{t("Prakiraan belum dapat dimuat. Periksa koneksi internet lalu coba kembali.")}</div>}{weather ? <><div className="weather-days">{weather.daily.time.map((day, index) => <div key={day}><span>{new Intl.DateTimeFormat(getLocale(), { weekday: 'short', timeZone: 'UTC' }).format(new Date(day + 'T12:00:00Z'))}</span><small>{day.slice(8, 10)}/{day.slice(5, 7)}</small>{(weather.daily.precipitation_sum[index] || 0) > 5 ? <CloudRain size={25} /> : <Thermometer size={25} />}<strong>{n(weather.daily.temperature_2m_max[index], 1)}°</strong><span>{n(weather.daily.precipitation_sum[index], 1)} {t("mm")}</span></div>)}</div><div className="weather-alert">{weather.daily.temperature_2m_max.some(value => value != null && value >= 35) || weather.daily.precipitation_sum.some(value => value != null && value >= 50) ? <><TriangleAlert size={19} /><span><strong>{t("Ambang pantauan terlampaui.")}</strong> {t("Terdapat prakiraan suhu ≥35°C atau hujan ≥50 mm/hari. Verifikasi dengan informasi meteorologi setempat.")}</span></> : <><CheckCheck size={19} /><span><strong>{t("Belum ada ambang pantauan terlampaui.")}</strong> {t("Prakiraan berada di bawah 35°C dan 50 mm/hari pada data yang tersedia.")}</span></>}</div><p className="fine-print">{t("Prakiraan titik")}{' '}{t(monitored.location)}{t(", bukan rata-rata nasional. Periode")}{' '}{weather.daily.time[0]}–{weather.daily.time.at(-1)} · {weather.timezone}{t(". Ambang ilustratif ini belum dikalibrasi untuk tanaman padi.")}</p></> : weatherState !== 'error' && <div className="weather-empty"><CloudRain size={31} /><div><strong>{t("Hubungkan kondisi cuaca ke wilayah pemantauan.")}</strong><p>{t("Prakiraan suhu maksimum dan hujan tersedia untuk tujuh hari. Cuaca aktual dari API ditampilkan terpisah dari skenario anomali iklim.")}</p></div></div>}</section><section className="card recommendation-card"><SectionHead title={t("Rekomendasi adaptasi")} subtitle={analysisMode || t("Analisis lokal · input iklim demo")} action={<span className="ai-tag"><Sparkles size={13} />{t("DECISION SUPPORT")}</span>} /><p className="recommendation-summary">{analysis?.summary || recommendation.summary}</p><div className="action-grid">{(analysis?.actions || recommendation.actions).map((action: string, index: number) => <div className="action-item" key={action}><span>{String(index + 1).padStart(2, '0')}</span><p>{action}</p><Check size={16} /></div>)}</div><p className="fine-print">{t("Rekomendasi untuk eksplorasi dan perencanaan awal. Validasi data lokal serta penilaian ahli tetap diperlukan.")}</p></section></>}
      {page === 'warnings' && <><div className="warning-summary-grid"><div className="warning-summary high"><TriangleAlert size={24} /><div><strong>{alerts.filter(row => row.risk.level === 'high' && (country === 'SEA' || country === row.code)).length}</strong><span>{t("Negara dengan skor tinggi")}</span></div></div><div className="warning-summary medium"><Activity size={24} /><div><strong>{alerts.filter(row => row.risk.level === 'medium' && (country === 'SEA' || country === row.code)).length}</strong><span>{t("Negara dalam status waspada")}</span></div></div><div className="warning-summary watched"><Bookmark size={24} /><div><strong>{watchlist.length}</strong><span>{t("Negara di daftar pantauan")}</span></div></div></div>{controls}{warningTable(true)}<div className="note-card"><Bell size={20} /><div><strong>{t("Peringatan mengikuti skenario yang dipilih.")}</strong><p>{t("Tahun, skenario pertumbuhan, dan tekanan hasil panen memperbarui skor secara langsung. Tombol bookmark menyimpan daftar pantauan pada browser ini. Dashboard belum mengirim notifikasi otomatis atau peringatan operasional.")}</p></div></div>{insightCard}</>}
      {page === 'spatio' && <SpatioTemporal />}
      {page === 'sources' && <Sources onMethod={() => setModal('method')} />}
      <footer><Logo small /><span>{t("An integrated perspective on Southeast Asia's food future.")}</span><span className="footer-status"><i />{t("Research prototype · v1.0")}</span></footer>
      </main>
    </div>
    {toast && <div className="toast" role="status"><Check size={17} />{toast}<button onClick={() => setToast('')} aria-label={t("Tutup notifikasi")}><X size={15} /></button></div>}
    {modal === 'method' && <Modal title={t("Metodologi & batasan")} wide onClose={() => setModal(null)}><div className="method-content"><p>{t("Rice Guard menghubungkan data terbuka dengan indikator yang dapat ditelusuri. Implementasi ini adalah prototipe penelitian, dengan metode berikut.")}</p><div className="method-section"><span>01</span><div><h3>{t("Data historis & cakupan")}</h3><p>{t("Produksi padi 1961–2024 berasal dari FAO melalui OWID (ton gabah). Populasi dari UN WPP melalui OWID; 2024 menggunakan kolom proyeksi UN. Agregat Asia Tenggara mencakup 11 negara, dengan produksi tersedia untuk 10 negara pada 2024. Data produksi Singapura tetap kosong, bukan nol.")}</p></div></div><div className="method-section"><span>02</span><div><h3>{t("Proyeksi yang transparan")}</h3><p>{t("For the regional outlook, Rice Guard uses the available forecasts with the lowest historical test errors for production and population. Forecasts extend to 2030. Country outlooks follow the trend in the latest 10 years of data. Harvest-loss scenarios reduce production gradually until the selected year. Regional and country totals can differ because their data coverage and forecasting methods differ.")}</p></div></div><div className="method-section"><span>03</span><div><h3>{t("Skor pantauan & input iklim")}</h3><p>{t("Padi per kapita = produksi (juta ton) ÷ populasi (juta jiwa) × 1.000. Skor = min(100, 4 × penurunan persentase per kapita + 13 × anomali suhu positif + 0,55 × nilai absolut perubahan hujan). Suhu dan perubahan hujan adalah input demo tanpa baseline observasi. Skor &lt;30 rendah, 30–54 waspada, ≥55 tinggi. Formula ilustratif ini belum dilatih atau divalidasi, dan tidak menilai kecukupan beras konsumsi.")}</p></div></div><div className="method-section"><span>04</span><div><h3>{t("AI & informasi cuaca")}</h3><p>{t("AI Climate Monitor mendukung layanan AI yang dikonfigurasi di server. Jika belum terhubung, rekomendasi dibuat dari aturan lokal dan diberi label. Prakiraan cuaca Open-Meteo diperoleh saat diminta, pada satu titik representatif per negara. Prakiraan cuaca tidak menggantikan data anomali iklim nasional.")}</p></div></div><div className="method-note">{t("Forecasts are estimates, not guarantees. Paddy is rice before milling. Production per person helps identify changes in supply, but food availability also depends on imports, exports, reserves, losses, and consumption. The risk score is an illustrative monitoring signal, not a probability of food shortage. Spatial uncertainty ranges do not capture every possible climate outcome.")}</div></div></Modal>}
    {modal === 'report' && <Modal title={t("Laporan pantauan Rice Guard")} onClose={() => setModal(null)}><div className="report-content"><span className="control-label">{countryName.toUpperCase()} {t("· SKENARIO")}{' '}{year}</span><h3>{t("Perspektif ketahanan pangan")}</h3><div className="report-values"><div><span>{t("Proyeksi padi")}</span><strong>{n(end.rice)} {t("juta ton")}</strong></div><div><span>{t("Proyeksi populasi")}</span><strong>{n(end.population)} {t("juta jiwa")}</strong></div><div><span>{t("Skor eksploratif")}</span><strong>{risk.score ?? '—'} / 100</strong></div><div><span>{t("Tren padi per kapita")}</span><strong>{pct(risk.change)}</strong></div></div><p>{t(recommendation.summary)}</p><ul>{recommendation.actions.map((action: string) => <li key={action}>{action}</li>)}</ul><p className="fine-print">{t("Outlook:")}{' '}{notebookActive ? t("Recommended forecast") : t(effectiveScenario)} {t("· Tekanan panen:")}{' '}{stress}{t("% · Data FAO/OWID dan UN/OWID. Input iklim demo. Belum mencakup konsumsi, perdagangan, atau stok pangan.")}</p><div className="report-actions"><button className="primary-button" onClick={exportCsv}><Download size={16} />{t("Unduh data CSV")}</button><button className="outline-button" onClick={() => window.print()}><FileText size={16} />{t("Cetak / simpan PDF")}</button></div></div></Modal>}
    {modal === 'help' && <Modal title={t("Tentang Rice Guard")} onClose={() => setModal(null)}><div className="about-content"><Logo /><p>{t("Rice Guard adalah dashboard eksploratif untuk forecasting produksi padi dan populasi, pemantauan iklim, serta indikator risiko pangan di Asia Tenggara, berdasarkan inovasi pada infografis RiceGuard.")}</p><h3>{t("Mulai dari wilayah yang ingin Anda pahami.")}</h3><p>{t("Pilih negara dan tahun proyeksi pada bar filter. Buka Forecasting untuk mengubah skenario, Risk Map untuk menelusuri negara, serta Climate Monitor untuk rekomendasi dan prakiraan cuaca dari API.")}</p><p>{t("Integrated Data explains the data sources and their coverage. Spatio-temporal shows harvested-area projections, climate scenarios, and uncertainty ranges.")}</p><button className="primary-button" onClick={() => { setModal(null); go('forecast'); }}>{t("Mulai eksplorasi")}{' '}<ArrowRight size={16} /></button></div></Modal>}
  </div>;
}

function Metric({ icon, label, value, unit, change, note, variant = '', warning = false }: { icon: ReactNode; label: string; value: string; unit: string; change?: number | null; note: string; variant?: string; warning?: boolean }) {
  return <section className={`metric card ${variant} ${warning ? 'metric-warning' : ''}`}><div className="metric-title"><span>{label}</span><div className="metric-icon">{icon}</div></div><div className="metric-value">{value}<span>{unit}</span></div><div className="metric-footer">{change != null ? <><span className={`metric-change ${change < 0 ? 'negative' : 'positive'}`}>{change < 0 ? <ArrowDownRight size={13} /> : <ArrowUpRight size={13} />}{pct(change)}</span><span>{label.startsWith(t("Padi per kapita")) ? t("dari 2024") : t("dari 2023")}</span></> : warning ? <span className="metric-warning-note"><span className="alert-dot" />{t("Perlu pemantauan lebih lanjut")}</span> : <span>{t("Data produksi belum tersedia")}</span>}</div><div className="metric-source">{note}</div><svg className="metric-spark" viewBox="0 0 92 28"><path d={warning ? 'M2 22 16 17 29 20 41 9 53 12 65 8 78 10 90 3' : variant === 'gold' ? 'M2 25 15 21 28 20 41 16 54 14 66 12 78 8 90 5' : 'M2 24 13 20 25 23 37 14 49 16 60 10 72 12 84 5 90 6'} fill="none" stroke="currentColor" strokeWidth="1.8" /></svg></section>;
}

function Sources({ onMethod }: { onMethod: () => void }) {
  const sources = [
    { name: t("Our World in Data / FAO"), initials: 'OW', domain: t("ourworldindata.org"), title: t("Produksi padi"), description: t("Data produksi tahunan dalam ton gabah. Snapshot 1961–2024 terintegrasi untuk 10 negara dengan data 2024; Singapura tidak tersedia."), url: 'https://ourworldindata.org/grapher/rice-production', status: t("Terintegrasi"), icon: Wheat },
    { name: t("Our World in Data / UN"), initials: 'UN', domain: t("ourworldindata.org"), title: t("Populasi"), description: t("Seri populasi 11 negara. Snapshot 1961–2024, dengan populasi 2024 berasal dari proyeksi UN pada dataset."), url: 'https://ourworldindata.org/grapher/population-with-un-projections', status: t("Terintegrasi"), icon: Users },
    { name: 'Open-Meteo', initials: 'OM', domain: t("open-meteo.com"), title: t("Prakiraan cuaca"), description: t("API suhu maksimum dan curah hujan 7 hari pada titik pemantauan. Dimuat saat diminta, memerlukan koneksi internet."), url: 'https://open-meteo.com/en/docs', status: t("API on demand"), icon: CloudRain },
    { name: t("Natural Earth"), initials: 'NE', domain: t("naturalearthdata.com"), title: t("Batas negara"), description: t("Geometri negara skala 1:110 juta untuk peta interaktif. Diunduh lokal; Singapura ditampilkan sebagai titik."), url: 'https://www.naturalearthdata.com/downloads/110m-cultural-vectors/110m-admin-0-countries/', status: t("Terintegrasi"), icon: MapIcon },
  ];
  return <><div className="note-card language-note"><Globe2 size={20}/><div><strong>{t("Language")}</strong><p>{t("English is the source language. Other languages are machine translations; check the English version for technical interpretation.")}</p></div></div><section className="card notebook-source"><SectionHead title={t("Forecast coverage")} subtitle={t("Regional outlook · 2025–2030")} /><div><p>{t("Rice Guard automatically selects the available production and population forecasts with the smallest errors when tested against past data. Country outlooks follow recent production and population trends.")}</p><p>{t("Harvested-area projections cover 10 ASEAN countries for 2030. Timor-Leste is not included in this analysis.")}</p></div></section><div className="data-overview card"><div className="data-icon"><Database size={31} strokeWidth={1.4} /></div><div><h3>{t("Asal data yang bisa ditelusuri.")}</h3><p>{t("Snapshot lokal menjaga dashboard tetap dapat digunakan tanpa jaringan. Prakiraan cuaca diperbarui secara terpisah melalui API.")}</p></div><div className="data-coverage"><strong>11</strong><span>{t("Negara tercakup")}</span></div><div className="data-coverage"><strong>64</strong><span>{t("Tahun historis")}</span></div></div><div className="sources-grid">{sources.map(source => <section className="card source-card" key={source.name}><div className="source-card-top"><span className="source-logo">{source.initials}</span><div><h3>{t(source.name)}</h3><span>{source.domain}</span></div><ExternalLink size={16} /></div><div className="source-type"><source.icon size={17} /><strong>{t(source.title)}</strong></div><p>{t(source.description)}</p><div className="source-card-bottom"><span><i />{t(source.status)}</span><a href={source.url} target="_blank" rel="noreferrer">{t("Lihat sumber")}{' '}<ArrowUpRight size={15} /></a></div></section>)}</div><section className="card planned-sources"><SectionHead title={t("Sumber penelitian spatio-temporal")} subtitle={t("Climate, boundaries, and harvested-area data used for the spatial outlook")} /><div>{[{ name: 'CHIRPS', detail: t("Curah hujan historis"), url: 'https://www.chc.ucsb.edu/data/chirps' }, { name: 'CMIP6', detail: t("Proyeksi iklim"), url: 'https://wcrp-cmip.org/cmip6/' }, { name: 'GADM', detail: t("Batas administrasi"), url: 'https://gadm.org/' }, { name: 'GloRice', detail: t("Distribusi area panen"), url: null }].map(item => <div key={item.name}><Layers3 size={19} /><span><strong>{t(item.name)}</strong><small>{t(item.detail)}</small></span>{item.url ? <a href={item.url} target="_blank" rel="noreferrer" aria-label={t("Sumber {p0}", {p0: item.name})}><ArrowUpRight size={16} /></a> : <span className="mini-badge">{t("INTEGRATED")}</span>}</div>)}</div></section><div className="note-card"><BookOpen size={22} /><div><strong>{t("Terbuka juga berarti jelas tentang batasannya.")}</strong><p>{t("Snapshot diunduh")}{' '}{new Intl.DateTimeFormat(getLocale(), { dateStyle: 'long', timeZone: 'Asia/Jakarta' }).format(new Date(snapshot.retrievedAt))}{t(". Atribusi FAO, UN, OWID, Open-Meteo, dan Natural Earth disertakan. Ketentuan sumber asli berlaku untuk penggunaan ulang. Formula risiko dan proyeksi dijelaskan pada metodologi.")}</p><button className="text-button" onClick={onMethod}>{t("Baca metodologi")}{' '}<ArrowRight size={14} /></button></div></div></>;
}

export default App;
